//! Plugin smoke tests — end-to-end verification that the WASM plugin host
//! (sentinel-plugins) correctly loads, evaluates, and applies plugin decisions.
//!
//! These tests use the hello-world example plugin compiled to WASM, so they
//! exercise the full stack: SDK → compile → load → evaluate → result.

use sentinel_core::{context::RequestContext, WafDecision};
use sentinel_plugins::{PluginEvalResult, PluginRuntime};

use std::net::{IpAddr, Ipv4Addr};
use std::path::Path;

/// Path to the hello-world example plugin WASM binary.
/// Generated by `cargo build --target wasm32-unknown-unknown --release` inside
/// `plugins/examples/hello-world/`.
fn hello_world_wasm_path() -> &'static Path {
    Path::new("plugins/examples/hello-world/target/wasm32-unknown-unknown/release/sentinel_plugin_hello_world.wasm")
}

/// Build a minimal RequestContext for testing.
fn make_ctx() -> RequestContext {
    let mut ctx = RequestContext::new(IpAddr::V4(Ipv4Addr::new(192, 168, 1, 100)), 54321);
    ctx.request_headers.insert(
        http::header::USER_AGENT,
        "Mozilla/5.0 (Test)".parse().unwrap(),
    );
    ctx.request_headers.insert(
        http::header::HOST,
        "example.com".parse().unwrap(),
    );
    ctx
}

// ---------------------------------------------------------------------------
// PluginRuntime basic operations
// ---------------------------------------------------------------------------

#[tokio::test]
async fn plugin_runtime_creates_successfully() {
    let rt = PluginRuntime::new().expect("create runtime");
    assert_eq!(rt.plugin_count(), 0);
}

#[tokio::test]
async fn evaluate_nonexistent_plugin_returns_allow() {
    let rt = PluginRuntime::new().unwrap();
    let ctx = make_ctx();
    let result = rt.evaluate_plugin("nonexistent", &ctx).await;
    assert_eq!(result.decision, WafDecision::Allow);
    assert_eq!(result.anomaly_score_delta, 0);
    assert!(result.pending_callouts.is_none());
}

#[tokio::test]
async fn load_plugin_increases_count() {
    let mut rt = PluginRuntime::new().unwrap();

    // Minimal WASM binary that exports `evaluate`.
    // This is a hand-crafted wasm module with a single exported function.
    let wasm = minimal_evaluate_wasm();
    rt.load_plugin("minimal", &wasm).unwrap();
    assert_eq!(rt.plugin_count(), 1);
}

#[tokio::test]
async fn plugin_names_returns_loaded_plugins() {
    let mut rt = PluginRuntime::new().unwrap();
    let wasm = minimal_evaluate_wasm();
    rt.load_plugin("plugin_a", &wasm).unwrap();
    rt.load_plugin("plugin_b", &wasm).unwrap();
    let names = rt.plugin_names();
    assert!(names.contains(&"plugin_a".to_string()));
    assert!(names.contains(&"plugin_b".to_string()));
    assert_eq!(names.len(), 2);
}

#[tokio::test]
async fn unload_plugin_removes_entry() {
    let mut rt = PluginRuntime::new().unwrap();
    let wasm = minimal_evaluate_wasm();
    rt.load_plugin("temp", &wasm).unwrap();
    assert_eq!(rt.plugin_count(), 1);
    rt.unload_plugin("temp");
    assert_eq!(rt.plugin_count(), 0);
}

#[tokio::test]
async fn evaluate_minimal_plugin_returns_allow() {
    let mut rt = PluginRuntime::new().unwrap();
    let wasm = minimal_evaluate_wasm();
    rt.load_plugin("minimal", &wasm).unwrap();
    let ctx = make_ctx();
    let result = rt.evaluate_plugin("minimal", &ctx).await;
    assert_eq!(result.decision, WafDecision::Allow);
    assert_eq!(result.anomaly_score_delta, 0);
    assert!(result.response_headers.is_empty());
}

#[tokio::test]
async fn evaluate_plugin_with_bad_wasm_returns_allow() {
    let mut rt = PluginRuntime::new().unwrap();
    // Load invalid WASM bytes — should fail gracefully.
    let result = rt.load_plugin("bad", b"not a valid wasm module");
    assert!(result.is_err());

    // Evaluating the bad plugin should still return Allow.
    let ctx = make_ctx();
    let result = rt.evaluate_plugin("bad", &ctx).await;
    assert_eq!(result.decision, WafDecision::Allow);
}

// ---------------------------------------------------------------------------
// Host ABI integration tests (via a minimal WASM that exercises the ABI)
// ---------------------------------------------------------------------------

#[tokio::test]
async fn host_log_is_callable_by_guest() {
    let mut rt = PluginRuntime::new().unwrap();
    let wasm = wasm_that_logs();
    rt.load_plugin("logger", &wasm).unwrap();
    let ctx = make_ctx();
    let result = rt.evaluate_plugin("logger", &ctx).await;
    // Logging should not affect the decision.
    assert_eq!(result.decision, WafDecision::Allow);
}

#[tokio::test]
async fn host_set_decision_block_is_honored() {
    let mut rt = PluginRuntime::new().unwrap();
    let wasm = wasm_that_blocks();
    rt.load_plugin("blocker", &wasm).unwrap();
    let ctx = make_ctx();
    let result = rt.evaluate_plugin("blocker", &ctx).await;
    assert_eq!(result.decision, WafDecision::Block);
}

#[tokio::test]
async fn host_add_score_accumulates() {
    let mut rt = PluginRuntime::new().unwrap();
    let wasm = wasm_that_scores();
    rt.load_plugin("scorer", &wasm).unwrap();
    let ctx = make_ctx();
    let result = rt.evaluate_plugin("scorer", &ctx).await;
    assert_eq!(result.anomaly_score_delta, 5);
}

#[tokio::test]
async fn host_get_req_header_reads_header() {
    let mut rt = PluginRuntime::new().unwrap();
    let wasm = wasm_that_checks_ua();
    rt.load_plugin("ua_check", &wasm).unwrap();
    let ctx = make_ctx();
    let result = rt.evaluate_plugin("ua_check", &ctx).await;
    // This plugin blocks if User-Agent contains "Test"
    assert_eq!(result.decision, WafDecision::Block);
}

#[tokio::test]
async fn host_kv_get_set_works() {
    let mut rt = PluginRuntime::new().unwrap();
    let wasm = wasm_that_uses_kv();
    rt.load_plugin("kv_user", &wasm).unwrap();
    let ctx = make_ctx();
    let _result = rt.evaluate_plugin("kv_user", &ctx).await;

    // After evaluate, the KV store should have the key set by the plugin.
    let val = rt.kv_store.get("test_key").map(|e| e.value().clone());
    assert_eq!(val, Some("hello_from_plugin".to_string()));
}

#[tokio::test]
async fn host_set_header_queues_response_header() {
    let mut rt = PluginRuntime::new().unwrap();
    let wasm = wasm_that_sets_header();
    rt.load_plugin("header_setter", &wasm).unwrap();
    let ctx = make_ctx();
    let result = rt.evaluate_plugin("header_setter", &ctx).await;
    assert_eq!(result.response_headers.len(), 1);
    assert_eq!(result.response_headers[0].0, "X-Custom");
    assert_eq!(result.response_headers[0].1, "plugin-value");
}

#[tokio::test]
async fn plugin_panics_return_safe_default() {
    let mut rt = PluginRuntime::new().unwrap();
    let wasm = wasm_that_panics();
    rt.load_plugin("crasher", &wasm).unwrap();
    let ctx = make_ctx();
    let result = rt.evaluate_plugin("crasher", &ctx).await;
    assert_eq!(result.decision, WafDecision::Allow);
    assert_eq!(result.anomaly_score_delta, 0);
}

// ---------------------------------------------------------------------------
// PluginEvalResult defaults
// ---------------------------------------------------------------------------

#[tokio::test]
async fn eval_result_defaults_are_safe() {
    let rt = PluginRuntime::new().unwrap();
    let ctx = make_ctx();
    let result: PluginEvalResult = rt.evaluate_plugin("nonexistent", &ctx).await;
    assert_eq!(result.decision, WafDecision::Allow);
    assert_eq!(result.anomaly_score_delta, 0);
    assert!(result.response_headers.is_empty());
    assert!(result.pending_callouts.is_none());
}

// ---------------------------------------------------------------------------
// Sandboxing tests
// ---------------------------------------------------------------------------

#[tokio::test]
async fn fuel_limit_traps_runaway_plugin() {
    let mut rt = PluginRuntime::new().unwrap();
    rt.set_fuel_limit(Some(50)); // tiny budget
    let wasm = wasm_that_loops();
    rt.load_plugin("looper", &wasm).unwrap();
    let ctx = make_ctx();
    let result = rt.evaluate_plugin("looper", &ctx).await;
    // Should trap before completing — we return Allow as safe default.
    assert_eq!(result.decision, WafDecision::Allow);
}

#[tokio::test]
async fn epoch_deadline_configurable() {
    let mut rt = PluginRuntime::new().unwrap();
    rt.set_epoch_deadline(Some(5_000_000));
    assert_eq!(rt.epoch_deadline(), Some(5_000_000));
    rt.set_epoch_deadline(None);
    assert_eq!(rt.epoch_deadline(), None);
}

#[tokio::test]
async fn memory_limit_configurable() {
    let mut rt = PluginRuntime::new().unwrap();
    rt.set_memory_limit("plugin-x", Some(4 * 1024 * 1024));
    assert_eq!(rt.memory_limit("plugin-x"), Some(4 * 1024 * 1024));
    rt.set_memory_limit("plugin-x", None);
    assert!(rt.memory_limit("plugin-x").is_none());
}

// ---------------------------------------------------------------------------
// Helpers — minimal WASM modules built via wat
// ---------------------------------------------------------------------------

/// A WASM module that exports `evaluate` and does nothing.
fn minimal_evaluate_wasm() -> Vec<u8> {
    wat::parse_str(
        r#"
(module
  (func (export "evaluate"))
)
"#,
    )
    .unwrap()
}

/// A WASM module that calls host_log.
fn wasm_that_logs() -> Vec<u8> {
    wat::parse_str(
        r#"
(module
  (import "env" "host_log" (func $host_log (param i32 i32)))
  (memory (export "memory") 1)
  (func (export "evaluate")
    i32.const 0
    i32.const 5
    call $host_log
  )
  (data (i32.const 0) "hello")
)
"#,
    )
    .unwrap()
}

/// A WASM module that calls host_set_decision(1) = Block.
fn wasm_that_blocks() -> Vec<u8> {
    wat::parse_str(
        r#"
(module
  (import "env" "host_set_decision" (func $host_set_decision (param i32)))
  (func (export "evaluate")
    i32.const 1
    call $host_set_decision
  )
)
"#,
    )
    .unwrap()
}

/// A WASM module that calls host_add_score(5).
fn wasm_that_scores() -> Vec<u8> {
    wat::parse_str(
        r#"
(module
  (import "env" "host_add_score" (func $host_add_score (param i32)))
  (func (export "evaluate")
    i32.const 5
    call $host_add_score
  )
)
"#,
    )
    .unwrap()
}

/// A WASM module that calls host_get_req_header for "user-agent" and blocks
/// if the header contains "Test".
fn wasm_that_checks_ua() -> Vec<u8> {
    wat::parse_str(
        r#"
(module
  (import "env" "host_get_req_header" (func $host_get_req_header (param i32 i32 i32 i32) (result i32)))
  (import "env" "host_set_decision" (func $host_set_decision (param i32)))
  (memory (export "memory") 1)
  (func (export "evaluate")
    ;; Write header name "user-agent" at offset 0
    ;; Call host_get_req_header(name=0, len=10, out=20, max=256) -> written
    i32.const 0
    i32.const 10
    i32.const 20
    i32.const 256
    call $host_get_req_header
    ;; If written > 0, the header exists — block
    (if (i32.gt_s (i32.const 0)) (then
      i32.const 1
      call $host_set_decision
    ))
  )
  (data (i32.const 0) "user-agent")
)
"#,
    )
    .unwrap()
}

/// A WASM module that calls host_kv_set("test_key", "hello_from_plugin").
fn wasm_that_uses_kv() -> Vec<u8> {
    wat::parse_str(
        r#"
(module
  (import "env" "host_kv_set" (func $host_kv_set (param i32 i32 i32 i32)))
  (memory (export "memory") 1)
  (func (export "evaluate")
    ;; key at offset 0, value at offset 20
    i32.const 0
    i32.const 8
    i32.const 20
    i32.const 18
    call $host_kv_set
  )
  (data (i32.const 0) "test_key")
  (data (i32.const 20) "hello_from_plugin")
)
"#,
    )
    .unwrap()
}

/// A WASM module that calls host_set_header("X-Custom", "plugin-value").
fn wasm_that_sets_header() -> Vec<u8> {
    wat::parse_str(
        r#"
(module
  (import "env" "host_set_header" (func $host_set_header (param i32 i32 i32 i32)))
  (memory (export "memory") 1)
  (func (export "evaluate")
    i32.const 0
    i32.const 8
    i32.const 20
    i32.const 12
    call $host_set_header
  )
  (data (i32.const 0) "X-Custom")
  (data (i32.const 20) "plugin-value")
)
"#,
    )
    .unwrap()
}

/// A WASM module that triggers an unreachable trap.
fn wasm_that_panics() -> Vec<u8> {
    wat::parse_str(
        r#"
(module
  (func (export "evaluate")
    unreachable
  )
)
"#,
    )
    .unwrap()
}

/// A WASM module with an infinite loop (tests fuel limiting).
fn wasm_that_loops() -> Vec<u8> {
    wat::parse_str(
        r#"
(module
  (func (export "evaluate")
    (loop
      br 0
    )
  )
)
"#,
    )
    .unwrap()
}
